const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const clientName = String(payload.clientName || payload.contactName || 'Valued Client').trim();
const companyName = String(payload.companyName || payload.company || 'Enterprise Partner').trim();
const contactEmail = String(payload.email || payload.contactEmail || '').trim();
const rawNotes = String(payload.consultationNotes || payload.notes || payload.requirements || '').trim();
const requestedCategory = String(payload.serviceCategory || payload.service || 'WEB_DEVELOPMENT').toUpperCase();

const validCategories = [
  'WEB_DEVELOPMENT', 'WEB_DESIGN', 'APP_DEVELOPMENT', 'MOBILE_DEVELOPMENT',
  'GAME_DEVELOPMENT', 'CUSTOM_SOFTWARE', 'SAAS_DEVELOPMENT', 'AI_AUTOMATION',
  'AI_AGENTS', 'DATABASE_ENGINEERING', 'API_INTEGRATION', 'ENTERPRISE_PLATFORM',
  'HEALTHCARE_TECH', 'CYBERSECURITY', 'TECHNICAL_CONSULTING'
];

const category = validCategories.includes(requestedCategory) ? requestedCategory : 'WEB_DEVELOPMENT';
const budgetIndication = String(payload.budget || '').toLowerCase();

return [{
  json: {
    eventId: item.eventId,
    clientName,
    companyName,
    contactEmail,
    consultationNotes: rawNotes,
    serviceCategory: category,
    budgetIndication,
    targetDeadlineDays: Number(payload.deadlineDays || 21)
  }
}];

const item = $input.first().json;
const cat = item.serviceCategory;
const budget = item.budgetIndication;

let selectedPackage = null;
let priceInINR = 8999;
let priceDisplay = '₹8,999';
let pricingModel = 'fixed';
let deliverables = [];

if (cat === 'WEB_DEVELOPMENT' || cat === 'WEB_DESIGN') {
  if (/enterprise|custom|50k|large/.test(budget)) {
    selectedPackage = 'Enterprise Web Platform';
    priceInINR = 50000;
    priceDisplay = '₹50,000+';
    pricingModel = 'milestone_based';
    deliverables = [
      'Custom Next.js App Router full-stack web application',
      'Supabase PostgreSQL schema with Row-Level Security',
      'Multi-region Vercel Edge deployment & automated CI/CD',
      'Payment gateway & administrative dashboard integration',
      '6-month comprehensive SLA & performance warranty'
    ];
  } else if (/pro|business|18k|19k|mid/.test(budget)) {
    selectedPackage = 'Business Pro Pack';
    priceInINR = 18999;
    priceDisplay = '₹18,999';
    pricingModel = 'milestone_based';
    deliverables = [
      'Up to 10 high-conversion responsive Next.js pages',
      'Razorpay payment gateway integration',
      'Admin content & quotation engine portal',
      'Automated email notification & webhook dispatchers',
      '3-month bug fix warranty and SLA'
    ];
  } else {
    selectedPackage = 'Digital Launch Pack';
    priceInINR = 8999;
    priceDisplay = '₹8,999';
    pricingModel = 'fixed';
    deliverables = [
      '5 core conversion-optimized responsive pages',
      'Modern Tailwind CSS design system',
      'Direct WhatsApp click-to-chat CTA & contact forms',
      'Search engine meta & schema.org structured data',
      '30-day post-launch warranty and bug fix guarantee'
    ];
  }
} else if (cat === 'APP_DEVELOPMENT' || cat === 'MOBILE_DEVELOPMENT') {
  selectedPackage = 'Cross-Platform Mobile App Sprint';
  priceInINR = 29999;
  priceDisplay = '₹29,999';
  pricingModel = 'milestone_based';
  deliverables = [
    'Flutter / React Native cross-platform mobile app',
    'Supabase Authentication & secure persistent storage',
    'Offline-first synchronization & responsive native UI',
    'App Store & Google Play Store release bundles',
    '60-day post-launch bug warranty'
  ];
} else if (cat === 'AI_AUTOMATION' || cat === 'AI_AGENTS') {
  selectedPackage = 'AI Workflow Orchestration Engine';
  priceInINR = 24999;
  priceDisplay = '₹24,999';
  pricingModel = 'milestone_based';
  deliverables = [
    'Groq LLaMA-3.3 70B inference pipeline integration',
    'RAG knowledge base embeddings with pgvector store',
    'Sub-120ms latency optimized FastAPI microservices',
    'Guardrails & automated anti-hallucination verification gates',
    'End-to-end telemetry and monitoring dashboard'
  ];
} else {
  selectedPackage = 'Custom Technical Engineering Package';
  priceInINR = 35000;
  priceDisplay = '₹35,000+';
  pricingModel = 'milestone_based';
  deliverables = [
    'Comprehensive technical architecture specification',
    'Production backend API endpoints & secure database modeling',
    'Integration test suite and security audit review',
    'Automated CI/CD deployment pipeline configuration',
    'System administrator handover runbook'
  ];
}

const advanceAmount = Math.round(priceInINR * 0.40);
const midAmount = Math.round(priceInINR * 0.40);
const finalAmount = priceInINR - advanceAmount - midAmount;

const paymentSchedule = [
  { milestone: 'M1 - Project Initiation & Advance', percentage: 40, amountINR: advanceAmount, due: 'Upon contract execution' },
  { milestone: 'M2 - Staging Prototype Verification', percentage: 40, amountINR: midAmount, due: 'Upon staging feature completion' },
  { milestone: 'M3 - Final Cutover & Handover', percentage: 20, amountINR: finalAmount, due: 'Upon production deployment sign-off' }
];

return [{
  json: {
    ...item,
    pricing: {
      packageId: selectedPackage.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
      packageName: selectedPackage,
      totalINR: priceInINR,
      totalDisplay: priceDisplay,
      pricingModel,
      paymentSchedule,
      deliverables
    }
  }
}];

const item = $input.first().json;
const totalDays = Math.max(14, item.targetDeadlineDays || 21);

const m1Days = Math.max(3, Math.round(totalDays * 0.20));
const m2Days = Math.max(5, Math.round(totalDays * 0.45));
const m3Days = Math.max(3, Math.round(totalDays * 0.20));
const m4Days = totalDays - m1Days - m2Days - m3Days;

const now = new Date();
const addDays = (d, count) => new Date(d.getTime() + count * 24 * 60 * 60 * 1000);

const m1Date = addDays(now, m1Days);
const m2Date = addDays(m1Date, m2Days);
const m3Date = addDays(m2Date, m3Days);
const m4Date = addDays(m3Date, m4Days);

const timelineMilestones = [
  {
    phase: 'Phase 1',
    title: 'Architecture Blueprint & UI/UX Design System',
    durationDays: m1Days,
    targetDate: m1Date.toISOString().split('T')[0],
    deliverables: ['System Architecture RFC', 'Figma Wireframe Prototype', 'API Contract Specification']
  },
  {
    phase: 'Phase 2',
    title: 'Core Feature Engineering & Database Modeling',
    durationDays: m2Days,
    targetDate: m2Date.toISOString().split('T')[0],
    deliverables: ['Production Backend Services', 'Frontend Component Suite', 'Staging Environment Preview']
  },
  {
    phase: 'Phase 3',
    title: 'Integration Testing, Security Audit & User Acceptance',
    durationDays: m3Days,
    targetDate: m3Date.toISOString().split('T')[0],
    deliverables: ['Core Web Vitals Verification', 'Security Headers Hardening', 'Client Acceptance Sign-Off']
  },
  {
    phase: 'Phase 4',
    title: 'Production Cutover & Warranty Period Initiation',
    durationDays: m4Days,
    targetDate: m4Date.toISOString().split('T')[0],
    deliverables: ['Production DNS Deployment', 'Credentials Handover Package', '30-Day Active Warranty Window']
  }
];

return [{
  json: {
    ...item,
    schedule: {
      estimatedTotalDays: totalDays,
      startDate: now.toISOString().split('T')[0],
      projectedCompletionDate: m4Date.toISOString().split('T')[0],
      warrantyDurationDays: 30,
      milestones: timelineMilestones
    }
  }
}];

const item = $input.first().json;
const crypto = require('crypto');
const proposalRef = 'LIT-PROP-' + crypto.randomBytes(4).toString('hex').toUpperCase();

const proposal = {
  reference: proposalRef,
  client: {
    name: item.clientName,
    company: item.companyName,
    email: item.contactEmail
  },
  serviceCategory: item.serviceCategory,
  executiveSummary: 'Logic Intelligence Technologies (LIT) proposal for ' + item.companyName + ' covering ' + item.pricing.packageName + ' with high-availability engineering, rigorous code quality, and predictable milestone delivery.',
  commercials: item.pricing,
  schedule: item.schedule,
  engineeringStandards: {
    targetCoreWebVitals: '99+ Performance score target',
    runtime: 'Modern Edge & Serverless Microservices',
    warranty: '30-day bug fix guarantee included in base contract',
    ipOwnership: 'Full client ownership of code and assets upon final payment'
  },
  signatory: {
    name: 'Vikash Saravanan',
    role: 'Lead System Engineer & Founder',
    organization: 'Logic Intelligence Technologies'
  },
  preparedAt: new Date().toISOString(),
  validUntil: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    status: 'processed',
    proposal
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: { proposal: item.json.proposal }
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
